head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDSTF09312";
scwin.secugrpId = "";       // 증권그룹ID — init 에서 상장형 수익증권(PF) (원본 fr_SecuGrpId)
scwin.mktId = "";           // 사용자 시장구분 — 1 유가는 사유를 찾기로, 2 코스닥은 직접 입력 (원본 fr_MktId)
scwin.isurCd = "";          // 고른 종목의 발행기관코드 (원본 vIsurCd)
scwin.listStatCd = "";      // 고른 종목의 상장상태코드 — D 면 버튼 전부 잠금 (원본 vListStatCd)
scwin.bzProcsNo = "";       // 이력에서 고른 건의 업무처리번호, 비면 신규 (원본 vBzProcsNo)
scwin.trJob = "";           // 처리구분 I: 저장, U: 수정, D: 삭제 (원본 trsIdx 1·2·3)
scwin.MKT_KSE = "1";                        // 유가증권시장
scwin.MKT_KOSDAQ = "2";                     // 코스닥시장
scwin.LIST_STAT_DELISTED = "D";             // 상장폐지 종목
scwin.RSNCD_DELIST = "4";                   // 사유 찾기 구분 — 상장폐지사유 (원본 RSNCD_DELIST)
// 원본 : /pf/ULDSTF09312.gfm (상장폐지 — 상장형 수익증권). gfm 은 저장소에 없고 W-Craft 1차 변환 + API 적용 개발 사본으로 분석했다.
/*
 * 화면 동작
 *  - [종목 찾기](ULDSTF92017_1)로 PF 종목을 고르면 상장증권수와 상장폐지 이력을 조회해 신규 입력 상태가 된다.
 *  - 이력 행을 누르면 그 건을 상세로 읽고, 상장폐지일이 오늘 이후면 수정·삭제·안내문작성, 지났으면 버튼을 잠근다.
 *    상장폐지 종목(상장상태 D)은 버튼을 전부 잠근다.
 *  - [저장]은 검증 → 확인 → 업무처리번호 채번 → 등록, [수정]은 검증 → 확인 → 수정,
 *    [삭제]는 시장안내공시 승인 여부 확인 → 확인 → 삭제. 성공하면 다시 조회하고 저장·수정한 건을 상세로 읽는다.
 *  - [안내문작성]은 개발 사본처럼 안내만 한다(공시안내문 연동은 원본 주석 잔재 — pf 계약서 §3).
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF09312/ULDSTF09312.md (§번호는 이 문서의 절)
 */

// 고정값
scwin.JOB_NM = { I : "저장", U : "수정", D : "삭제" };

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다.
scwin.BTN_MAP = {
    save : "btn_Save",          // [저장]
    modify : "btn_Update",      // [수정]
    "delete" : "btn_Delete",    // [삭제]
    guide : "btn_Dscl"          // [안내문작성]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09312.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 로딩 — 증권그룹·사용자 시장 → 버튼 신규 상태 → 시장별 사유 입력 방식 → 달력·조회 Enter 키 바인딩. 초기 조회는 없다. (원본 init — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 증권그룹·사용자 시장 — 원본 전역 fr_SecuGrpId·fr_MktId
    scwin.secugrpId = $c.lc.getGlbValue("SECUGRP_ID_PF");
    scwin.mktId = String($c.session.getUserInfo("market") ?? "");

    // 2) 버튼 — 신규 상태(저장만 활성)
    $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);

    // 3) 사용자 시장별 사유 입력 방식 — 코스닥은 직접 입력(원본 fn_CheckForm 의 시장 분기)
    scwin.setComponentByMkt(scwin.mktId);

    // 4) 달력 검사 바인딩(1회, 규칙 37) · 조회 영역 Enter 키(규칙 22)
    $c.date.checkCalendarFormat(cal_delistDd, "yyyyMMdd");
    $c.win.setEnterKeyEvent(tbl_search, scwin.btn_Search_onclick);
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_FindIsu_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목 찾기(돋보기) 버튼 클릭 — 고르면 상장증권수·이력을 조회한다. (원본 btn_isuNm onclick — §4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_FindIsu_onclick = async function (e) {
    try {
        await scwin.openIsuPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09312.btn_FindIsu_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 버튼 클릭 — 종목을 골랐는지 확인하고 조회한다. (원본 btn_search onclick — §4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Search_onclick = async function (e) {
    try {
        if ($c.util.isEmpty(dma_search.get("isuCd"))) {
            // com_req_select "[종목](을)를 선택하세요." 계열 공통 메시지
            await $c.win.alert($c.data.getMessage("com_req_select", "종목"));
            ibx_isuCd.focus();
            return;
        }
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09312.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_FindRsn_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 상장폐지사유 찾기(돋보기) 버튼 클릭. (원본 btn_delistRsnDsc onclick — §4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_FindRsn_onclick = async function (e) {
    try {
        await scwin.openRsnPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09312.btn_FindRsn_onclick" });
    }
};

/**
 * @method
 * @name scwin.grd_List_oncellclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 이력 행 클릭 — 그 건을 상세로 읽는다. (원본 grd_list oncellclick — §4)
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 열 id
 * @returns
 * @hidden N
 */
scwin.grd_List_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        if (rowIndex < 0) return;
        await scwin.selectDetail(String(dlt_list.getCellData(rowIndex, "bzProcsNo") ?? ""));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09312.grd_List_oncellclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Save_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 저장 버튼 클릭. (원본 btn_save onclick — §4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Save_onclick = async function (e) {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09312.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Update_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 수정 버튼 클릭. (원본 btn_update onclick — §4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Update_onclick = async function (e) {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09312.btn_Update_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Delete_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 삭제 버튼 클릭. (원본 btn_delete onclick — §4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Delete_onclick = async function (e) {
    try {
        await scwin.remove();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09312.btn_Delete_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Dscl_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 안내문작성 버튼 클릭. (원본 btn_dscl onclick — §4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Dscl_onclick = async function (e) {
    try {
        await scwin.writeDscl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09312.btn_Dscl_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectTotStkCnt
 * @author Inswave
 * @date 2026. 10. 30
 * @description 액면가·상장증권수 조회 → dma_detail(parval·listShrs). (원본 fn_isubook_read_sync — §5.1)
 * @param {String} isuCd 종목코드
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectTotStkCnt = async function (isuCd) {
    const sbmOptions = {
        id : "sbm_selectTotStkCnt",
        method : "get",
        action : "/api/listing/lstproc/pf/delisting/select-tot-stk-cnt",
        target : "dma_detail=body",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { isuCd : isuCd });
    if (result?.skipped) return false;      // 진행 중 조회가 있어 이번 호출은 건너뜀
    return result?.responseJSON?.success === true;
};

/**
 * @method
 * @name scwin.selectList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 상장폐지 이력 조회 → dlt_list. (원본 fn_list_sync — §5.2)
 * @param {String} isuCd 종목코드
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectList = async function (isuCd) {
    const sbmOptions = {
        id : "sbm_selectList",
        method : "get",
        action : "/api/listing/lstproc/pf/delisting/select-list",
        target : "dlt_list=body",
        gridview : "grd_List",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { isuCd : isuCd });
    if (result?.skipped) return false;      // 진행 중 조회가 있어 이번 호출은 건너뜀
    return result?.responseJSON?.success === true;
};

/**
 * @method
 * @name scwin.selectDetail
 * @author Inswave
 * @date 2026. 10. 30
 * @description 상장폐지 상세 조회 → dma_detail, 끝나면 버튼 상태를 정한다. (원본 fn_read_sync — §5.3)
 * @param {String} bzProcsNo 업무처리번호
 * @returns
 * @hidden N
 */
scwin.selectDetail = async function (bzProcsNo) {
    scwin.bzProcsNo = bzProcsNo;

    const sbmOptions = {
        id : "sbm_selectDetail",
        method : "get",
        action : "/api/listing/lstproc/pf/delisting/select-one",
        target : "dma_detail=body",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { bzProcsNo : bzProcsNo });
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    if (result?.responseJSON?.success !== true) return;

    scwin.applyButtonState();
};

/**
 * @method
 * @name scwin.saveTrs
 * @author Inswave
 * @date 2026. 10. 30
 * @description 등록(I)·수정(U)·삭제(D) 전송 — 상세에 종목·발행기관·시장조치적용대상(종목별 1)을 채워 보낸다.
 * 성공하면 안내 → 입력 초기화 → 다시 조회하고, 저장·수정이면 그 건을 상세로 읽는다. (원본 fn_trs — §5.4)
 * @param {String} trJob 처리구분 I·U·D
 * @returns
 * @hidden N
 */
scwin.saveTrs = async function (trJob) {
    const jobNm = scwin.JOB_NM[trJob] ?? "";
    const savedNo = scwin.bzProcsNo;

    dma_detail.set("isuCd", dma_search.get("isuCd"));
    dma_detail.set("isurCd", scwin.isurCd);
    dma_detail.set("mktactApplObjTpCd", "1");       // 시장조치적용대상구분 1 종목별 (원본 그대로)

    // 처리구분 → 화면 적용 API (원본 fn_trs 의 trsIdx 1·2·3 분기) — 전체 경로 리터럴(규칙 38)
    const sbmOptions = {
        id : "sbm_saveTrs",
        method : "post",
        action : (trJob === "I") ? "/api/listing/lstproc/pf/delisting/register"
               : (trJob === "U") ? "/api/listing/lstproc/pf/delisting/modify"
                                 : "/api/listing/lstproc/pf/delisting/remove",
        ref : "dma_detail",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀
    // TODO: register·modify·remove 응답 정의가 화면에 없다 — 통신 성공(success)만으로 판정한다 (§10 #4)
    if (result?.responseJSON?.success !== true) return;

    await $c.win.alert($c.data.getMessage("com_complete_0150", jobNm));

    scwin.initItem();
    if (!await scwin.selectList(dma_search.get("isuCd"))) return;
    tbx_totCnt.setValue(dlt_list.getRowCount());

    if (trJob !== "D") {
        await scwin.openSavedDetail(savedNo);
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.setComponentByMkt
 * @author Inswave
 * @date 2026. 10. 30
 * @description 사용자 시장별 상장폐지사유 입력 방식 — 유가는 찾기 팝업으로만, 코스닥은 직접 입력(찾기 버튼 잠금).
 * (원본 fn_CheckForm 의 시장 분기 — 개발 사본은 입력칸이 늘 읽기 전용이었다, §8 #3)
 * @param {String} mktId 사용자 시장구분
 * @returns
 * @hidden N
 */
scwin.setComponentByMkt = function (mktId) {
    const isKosdaq = (mktId === scwin.MKT_KOSDAQ);
    ibx_delistRsnDsc.setReadOnly(!isKosdaq);
    btn_FindRsn.setDisabled(isKosdaq);
};

/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목 찾기(ULDSTF92017_1) — 고른 종목·발행기관·상장상태를 담고 다시 조회한다. 상장폐지 종목이면 버튼을 전부 잠근다.
 * 취소·닫기면 아무것도 하지 않는다. (원본 btn_isuNm onclick — §6.1)
 * @returns
 * @hidden N
 */
scwin.openIsuPopup = async function () {
    const result = await $c.lc.popFindIsuAll({ secugrpId : scwin.secugrpId });
    // 취소·닫기(X)도 { isCloseButtonClick } 객체가 온다 → 종목코드로 판정(개발 사본은 판정 없이 값을 넣었다, §8 #2)
    if (result?.isCloseButtonClick === true || $c.util.isEmpty(result?.isuCd)) return;

    dma_search.set("isuCd", result.isuCd);
    dma_search.set("isuNm", result.isuKorNm ?? "");
    scwin.isurCd = String(result.isurCd ?? "");
    scwin.listStatCd = String(result.listStatCd ?? "");

    await scwin.search();
};

/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 — 입력을 신규 상태로 비우고 상장증권수 → 이력 순서로 조회해 건수를 적는다. 상장폐지 종목이면 버튼을 잠근다.
 * (원본 btn_search onclick·btn_isuNm onclick — §6.2)
 * @returns
 * @hidden N
 */
scwin.search = async function () {
    scwin.initItem();
    dlt_list.removeAll();
    tbx_totCnt.setValue("0");

    const isuCd = dma_search.get("isuCd");
    if (!await scwin.selectTotStkCnt(isuCd)) return;
    if (!await scwin.selectList(isuCd)) return;
    tbx_totCnt.setValue(dlt_list.getRowCount());

    if (scwin.listStatCd === scwin.LIST_STAT_DELISTED) {
        $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);
    }
};

/**
 * @method
 * @name scwin.initItem
 * @author Inswave
 * @date 2026. 10. 30
 * @description 입력 초기화 — 버튼 신규 상태, 상세 비우기, 업무처리번호 비우기. 통신 없음. (원본 fn_initItem — §6.3)
 * @returns
 * @hidden N
 */
scwin.initItem = function () {
    $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
    dma_detail.setEmptyValue();
    scwin.bzProcsNo = "";
};

/**
 * @method
 * @name scwin.openRsnPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 상장폐지사유 찾기(ULDSTF92008). 고른 사유 코드·사유·근거규정을 상세에 채운다. 취소·닫기면 아무것도 하지 않는다.
 * (원본 btn_delistRsnDsc onclick — 개발 사본은 사유 코드를 채우지 않아 유가 검증이 늘 실패했다, §8 #1)
 * @returns
 * @hidden N
 */
scwin.openRsnPopup = async function () {
    const res = await $c.lc.popFindClssLstRsnCd(scwin.RSNCD_DELIST, { mkt : scwin.MKT_KSE, rsn : "05" });
    if (res?.isCloseButtonClick === true || $c.util.isEmpty(res?.code)) return;    // 취소·닫기

    dma_detail.set("delistRsnCd", res.code);
    dma_detail.set("delistRsnDsc", res.name ?? "");
    dma_detail.set("grndRegulNm", res.regl ?? "");
};

/**
 * @method
 * @name scwin.applyButtonState
 * @author Inswave
 * @date 2026. 10. 30
 * @description 상세를 읽은 뒤 버튼 상태. 업무처리번호가 없으면 insert, 상장폐지일이 오늘 뒤면 update, 오늘이거나 지났으면 error,
 * 상장폐지 종목이면 disabled. (원본 fn_read_sync 의 setButtonSetWithDate(cal_delistDd, false) — §6.4)
 * @returns
 * @hidden N
 */
scwin.applyButtonState = function () {
    if ($c.util.isEmpty(scwin.bzProcsNo)) {
        $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
    } else {
        // 개발 사본은 그룹·매핑 없이 두 인자로만 불러 버튼이 바뀌지 않았다(§8 #4)
        $c.stf.setButtonSetWithDate(cal_delistDd, false, "grpBtnBox", scwin.BTN_MAP);
    }
    if (scwin.listStatCd === scwin.LIST_STAT_DELISTED) {
        $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);
    }
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 30
 * @description 저장·수정 전 입력 검증 — 종목, 상장폐지일(필수·현재일 이후), 상장폐지사유(유가는 찾기로 고른 코드, 코스닥은 직접 입력),
 * 근거규정(필수·200자). (원본 fn_CheckForm — §6.5)
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
 */
scwin.validate = async function () {
    const delistDd = String(dma_detail.get("delistDd") ?? "");

    // 1) 종목
    if ($c.util.isEmpty(dma_search.get("isuCd"))) {
        await $c.win.alert("[종목코드]를 선택하세요.");
        ibx_isuCd.focus();
        return false;
    }

    // 2) 상장폐지일 필수 · 현재일 이후
    if ($c.util.isEmpty(delistDd)) {
        await $c.win.alert("[상장폐지일]을 입력하세요.");
        cal_delistDd.focus();
        return false;
    }
    if ($c.date.getServerDateTime("yyyyMMdd") >= delistDd) {
        await $c.win.alert("[상장폐지일]을 현재일이후로 입력하세요.");
        cal_delistDd.focus();
        return false;
    }

    // 3) 상장폐지사유 — 코스닥은 직접 입력, 유가는 찾기로 고른 코드
    if (scwin.mktId === scwin.MKT_KOSDAQ) {
        if ($c.util.isEmpty(dma_detail.get("delistRsnDsc"))) {
            await $c.win.alert("[상장폐지사유]를 입력하세요.");
            ibx_delistRsnDsc.focus();
            return false;
        }
    } else if (scwin.mktId === scwin.MKT_KSE) {
        if ($c.util.isEmpty(dma_detail.get("delistRsnCd"))) {
            await $c.win.alert("[상장폐지사유]를 선택하세요.");
            btn_FindRsn.focus();
            return false;
        }
    }

    // 4) 근거규정 필수 · 200자 (개발 사본 maxLength 200)
    if ($c.util.isEmpty(dma_detail.get("grndRegulNm"))) {
        await $c.win.alert("[근거규정]을 입력하세요.");
        ibx_grndRegulNm.focus();
        return false;
    }
    const grndOptions = {
        validateType : "alert",
        checkType : "single",
        fields : {
            ibx_grndRegulNm : { maxLength : 200, name : "근거규정" }
        }
    };
    return await $c.validate.validateDataCollect(panel_Item, grndOptions);
};

/**
 * @method
 * @name scwin.getBzProcsNoOf
 * @author Inswave
 * @date 2026. 10. 30
 * @description 채번 응답에서 업무처리번호를 꺼낸다 — 문자열이면 그대로, 객체면 bzProcsNo. (pcc getNewBzProcNo 는 응답 JSON 을 그대로 돌려준다)
 * @param {*} body 채번 응답 body
 * @returns {String} 업무처리번호 (없으면 빈 문자열)
 * @hidden N
 */
scwin.getBzProcsNoOf = function (body) {
    if (body === null || body === undefined) return "";
    if (typeof body === "object") return String(body.bzProcsNo ?? "");
    return String(body);
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 저장 — 검증 → 확인 → 업무처리번호 채번(14자리 확인) → 등록. (원본 fn_save — §6.6)
 * @returns
 * @hidden N
 */
scwin.save = async function () {
    scwin.trJob = "I";

    if (!await scwin.validate()) return;
    // "[저장] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    // TODO: pcc 채번은 주식 변경상장 경로(stock/chglisting/new-bzprocsno)다 — PF 상장폐지도 같은 채번인지 확인 (§10 #3)
    const res = await $c.stf.getNewBzProcNo();
    const bzProcsNo = scwin.getBzProcsNoOf(res?.body ?? res);
    if (bzProcsNo.length !== 14) {
        await $c.win.alert($c.data.getMessage("com_complete_0151", "업무처리번호생성"));
        return;
    }

    scwin.bzProcsNo = bzProcsNo;
    dma_detail.set("bzProcsNo", bzProcsNo);
    await scwin.saveTrs(scwin.trJob);
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 10. 30
 * @description 수정 — 검증 → 확인 → 수정. (원본 fn_update — §6.7)
 * @returns
 * @hidden N
 */
scwin.update = async function () {
    scwin.trJob = "U";

    if (!await scwin.validate()) return;
    // "[수정] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.saveTrs(scwin.trJob);
};

/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 10. 30
 * @description 삭제 — 시장안내공시가 이미 승인된 건이면 막고, 확인을 받은 뒤 삭제한다. 입력 검증은 하지 않는다. (원본 fn_delete — §6.8)
 * @returns
 * @hidden N
 */
scwin.remove = async function () {
    scwin.trJob = "D";

    // TODO: pcc checkDeleteDiscls 는 target 을 문자열로 조립(dtsObj + "=body")하면서 dtsObj.get 도 부른다 —
    //       dataMap 을 넘기면 target 이 깨지는 결함(ULDSTF05232 와 같음), pcc 수정 요청 (§10 #5)
    if (!await $c.lc.checkDeleteDiscls(dma_bzCheck, scwin.bzProcsNo)) return;
    // "[삭제] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.saveTrs(scwin.trJob);
};

/**
 * @method
 * @name scwin.openSavedDetail
 * @author Inswave
 * @date 2026. 10. 30
 * @description 저장·수정 뒤 다시 조회한 이력에서 그 건을 찾아 선택·상세 조회한다. 찾지 못하면 원본처럼 마지막 행을 읽는다.
 * (원본 fn_trs 성공 분기의 setFocusedCell(마지막 행) + fn_read_sync — §6.9)
 * @param {String} bzProcsNo 저장·수정한 건의 업무처리번호
 * @returns
 * @hidden N
 */
scwin.openSavedDetail = async function (bzProcsNo) {
    const rowCount = dlt_list.getRowCount();
    if (rowCount === 0) return;

    let rowIndex = rowCount - 1;
    for (let i = 0; i < rowCount; i++) {
        if (String(dlt_list.getCellData(i, "bzProcsNo") ?? "") === bzProcsNo) {
            rowIndex = i;
            break;
        }
    }
    grd_List.setFocusedCell(rowIndex, 0);
    await scwin.selectDetail(String(dlt_list.getCellData(rowIndex, "bzProcsNo") ?? ""));
};

